import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"把 Ershu 启动到可登录状态","description":"准备 Ershu 的本地依赖和进程，并确认网页已经可以连接 API。","frontmatter":{"page_id":"guide-quick-start","description":"准备 Ershu 的本地依赖和进程，并确认网页已经可以连接 API。"},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1786290726000}'),p={name:"guide/quick-start.md"};function l(t,s,h,r,d,o){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="把-ershu-启动到可登录状态" tabindex="-1">把 Ershu 启动到可登录状态 <a class="header-anchor" href="#把-ershu-启动到可登录状态" aria-label="Permalink to &quot;把 Ershu 启动到可登录状态&quot;">​</a></h1><p>本页面向已经取得内部组件访问权限的维护者。目标不是完成分析，而是把基础设施、API、Worker 和前端启动到可以继续配置的状态。</p><div class="warning custom-block"><p class="custom-block-title">当前不能从公开包源直接安装</p><p>组合仓库和后端模块仍从私有开发源取得 Core 等依赖。没有对应的 Git 和 SSH 权限时，<code>uv sync --all-extras --frozen</code> 会在取得依赖时失败。目前没有可替代的公开安装命令。</p></div><p>下面的命令来自当前仓库清单和 README。它们说明应如何操作，不代表已经在你的机器上执行成功。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>开始前确认你具备：</p><ul><li>Python 3.14；</li><li>UV；</li><li>Docker 和 Docker Compose；</li><li>Node.js 24；</li><li>对当前私有组件源的访问权限；</li><li>与后端版本匹配的独立 <code>frontend</code> 仓库检出。</li></ul><p>Core 是共享包，不单独启动进程。网页完成第一次分析至少需要 PostgreSQL、Milvus 等基础设施、API、Worker 和前端。MCP 和仓库轮询进程按使用场景另行启动。</p><h2 id="第-1-步-启动基础设施" tabindex="-1">第 1 步：启动基础设施 <a class="header-anchor" href="#第-1-步-启动基础设施" aria-label="Permalink to &quot;第 1 步：启动基础设施&quot;">​</a></h2><p>在 <code>ershu</code> 组合仓库中复制 Compose 配置：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>打开 <code>.env.compose</code>，替换示例中的 PostgreSQL 和 MinIO 密码，然后启动服务：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>成功后，<code>ps</code> 列出的 PostgreSQL、Redis、Milvus、etcd 和 MinIO 服务应处于运行状态。如果其中一项反复重启，先查看对应容器日志，不要继续执行数据库迁移。</p><h2 id="第-2-步-准备后端配置" tabindex="-1">第 2 步：准备后端配置 <a class="header-anchor" href="#第-2-步-准备后端配置" aria-label="Permalink to &quot;第 2 步：准备后端配置&quot;">​</a></h2><p>复制当前配置模板：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>按文件注释替换示例密码和密钥，并确认数据库、Redis 与 Milvus 地址指向上一步启动的服务。模型名称、模型 API Key 和模型地址不要写进 <code>.env</code>；它们稍后在网页的模型通道中配置。</p><p>完成后，你应有一份仅供本地环境使用的 <code>.env</code>，其中不再保留准备用于真实环境的示例密钥。</p><h2 id="第-3-步-安装后端并执行迁移" tabindex="-1">第 3 步：安装后端并执行迁移 <a class="header-anchor" href="#第-3-步-安装后端并执行迁移" aria-label="Permalink to &quot;第 3 步：安装后端并执行迁移&quot;">​</a></h2><p>只有具备私有组件源访问权限时，才能执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-extras</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> head</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>成功判据是两条命令都以退出码 <code>0</code> 结束。若第一条命令无法取得 Core 或其他 Ershu 包，这是当前公开安装限制，不应通过删除锁文件或改用未经核实的包来绕过。</p><h2 id="第-4-步-启动-api-和-worker" tabindex="-1">第 4 步：启动 API 和 Worker <a class="header-anchor" href="#第-4-步-启动-api-和-worker" aria-label="Permalink to &quot;第 4 步：启动 API 和 Worker&quot;">​</a></h2><p>分别打开两个终端，并让进程保持运行。</p><p>终端 A：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>终端 B：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-worker</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在浏览器访问 <code>http://127.0.0.1:8000/health</code>。API 可用时会返回状态为 <code>ok</code> 的响应。这个地址只确认 API 进程存活；<code>/api/v1/health/dependencies</code> 还会检查数据库和 Milvus，但不检查 Redis。</p><p>Worker 当前没有网页健康检查。进程应持续运行且不立即退出；稍后的第一次运行能从队列继续推进，才是最终验证。</p><p>如果需要 MCP，再开一个终端运行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-mcp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果需要按仓库计划自动检查提交，再单独运行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api-poller</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这两个进程不是完成首次网页分析的前置条件。</p><h2 id="第-5-步-启动前端" tabindex="-1">第 5 步：启动前端 <a class="header-anchor" href="#第-5-步-启动前端" aria-label="Permalink to &quot;第 5 步：启动前端&quot;">​</a></h2><p>进入独立的 <code>frontend</code> 仓库：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>开发服务器默认使用 <code>http://localhost:3000</code>，并把 <code>/api</code> 转发到 <code>http://localhost:8000</code>。如果 API 在其他地址，修改 <code>.env.local</code> 中的 <code>VITE_DEV_API_PROXY</code> 后重启开发服务器。</p><p>成功后，打开 <code>http://localhost:3000</code>：</p><ul><li>全新数据库会跳转到首次管理员设置页；</li><li>已经存在用户的数据库会跳转到登录页；</li><li>页面若持续报网络错误，说明前端尚未连接到 API。</li></ul><p>现在可以继续<a href="./create-first-project">创建第一个项目</a>。</p>`,43)])])}const u=a(p,[["render",l]]);export{k as __pageData,u as default};
